// Telephone / Radio Band: Suno Studio audio effect (applied to rendered audio, not a lyric tag).
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Bandpass: g.biquad highpass at 'lowCut' (default 300Hz) then g.biquad lowpass at 'highCut'
//      (default 3400Hz) to squeeze the signal into the narrow telephone band.
//   3. Drive: scale by 'drive' (dB via g.dbToLin) then g.tanh for a crunchy radio edge.
//   4. Dry/wet: g.lerp between trimmed dry and processed by 'dry/wet mix'.
//   5. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var lowCut = g.input('lowCut');
  var highCut = g.input('highCut');
  var driveDb = g.input('drive');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var driveLin = g.dbToLin(driveDb);
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var hp = g.biquad({ input: trimmed, cutoff: lowCut, resonance: g.constant(0.9), mode: 'highpass' });
    var band = g.biquad({ input: hp, cutoff: highCut, resonance: g.constant(0.9), mode: 'lowpass' });
    var driven = g.tanh(g.mul(band, driveLin));
    var wet = g.lerp(mix, trimmed, driven);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
